// Operator-run, never in CI (needs a full fcp clone, gh, and a read-only Jira token in env):
//   node --import tsx scripts/gold-mine.ts --fcp ~/src/fcp --since 540d --out ../byte-gold/candidates
import { execFileSync } from "node:child_process";

const PR_IN_SUBJECT = /\(#(\d+)\)$/; // fcp squash merges: "[FE] RH-6589: ... (#2445)"
const SKIP = /(^|\/)(tests?|e2e)\/|(^|\/)(package-lock\.json|uv\.lock)$|_pb2(_grpc)?\.py$/;
const HUNK = /^@@ -(\d+)(?:,(\d+))? /;

const git = (fcp: string, ...args: string[]): string =>
  execFileSync("git", ["-C", fcp, ...args], { encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });

// SZZ: the old-side lines a fix changed, blamed at the fix's parent, point at the PR that wrote them.
export function introducingPrs(fcp: string, fixSha: string): Map<number, number> {
  const blamedLines = new Map<number, number>(); // PR number -> lines it wrote that the fix changed
  let path = "";
  for (const line of git(fcp, "diff", "-U0", `${fixSha}^`, fixSha).split("\n")) {
    if (line.startsWith("--- a/")) path = line.slice(6);
    const hunk = HUNK.exec(line);
    const count = Number(hunk?.[2] ?? 1);
    if (hunk === null || count === 0 || SKIP.test(path)) continue; // pure additions have nothing to blame
    const from = Number(hunk[1]);
    const porcelain = git(fcp, "blame", "-w", "-M", "-C", "--porcelain", `-L${from},${from + count - 1}`, `${fixSha}^`, "--", path);
    for (const sha of porcelain.match(/^[0-9a-f]{40}(?= \d+ \d+)/gm) ?? []) {
      const pr = Number(PR_IN_SUBJECT.exec(git(fcp, "log", "-1", "--format=%s", sha).trim())?.[1]);
      if (pr > 0) blamedLines.set(pr, (blamedLines.get(pr) ?? 0) + 1);
    }
  }
  return blamedLines;
}
// Row in candidates/real.jsonl: { id, bugKey, fixPr, introPr, blamedLines, daysToFix, changedLines }

import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { BrokerSession, type BrokerCommandResult } from "./broker.js";

// `byte broker --replay /input`: Byte's usual gh reads, answered from a sealed
// pack. No token, no network. Every replay is a first review, so the review
// and comment listings are empty; anything the pack can't answer is refused.
export async function replaySession(inputDir: string, outputDir: string, capability: string): Promise<BrokerSession> {
  const pr = JSON.parse(await readFile(join(inputDir, "pr.json"), "utf8")) as ReplayPr;
  const diff = await readFile(join(inputDir, "diff.patch"), "utf8");
  const ok = (stdout: string): BrokerCommandResult => ({ exitCode: 0, stdout, stderr: "" });
  const published: unknown[] = [];
  return new BrokerSession({
    repository: pr.repository,
    prNumber: pr.number,
    headSha: pr.headSha,
    token: "", // nothing to leak: both GitHub paths below are injected
    forbiddenSecrets: [capability],
    executeRead: async (args) => {
      if (args[0] === "pr" && args[1] === "diff") return ok(diff);
      if (args[0] === "pr" && args[1] === "view") return ok(JSON.stringify(pick(pr.view, jsonFields(args))));
      if (args[0] === "api" && /\/pulls\/\d+\/files/.test(args[1] ?? "")) return ok(JSON.stringify(pr.files));
      if (args[0] === "api" && /\/(pulls|issues)\/\d+\/(reviews|comments)/.test(args[1] ?? "")) return ok("[]");
      return { exitCode: 1, stdout: "", stderr: "not in the replay pack" };
    },
    // New optional injection in BrokerSessionOptions: publications are recorded, never posted.
    api: recordingApi(async (review) => {
      published.push(review);
      await writeFile(join(outputDir, "publication.json"), `${JSON.stringify(published, null, 2)}\n`);
      return { id: published.length };
    }),
  });
}

// SECURITY.md keeps model text out of commit messages. The one trailer added
// here is not model text: it is the gate-validated requester login, so G0's
// independent-approval check on main can see who asked for the fix and
// require an approval from someone else.
const REQUESTER_LOGIN = /^[A-Za-z0-9-]{1,39}$/;

function requestedBy(requester: string): string {
  if (!REQUESTER_LOGIN.test(requester)) {
    throw new Error("fix requester is not a GitHub login");
  }
  return `Requested-by: ${requester}`;
}

export function renderFixCommitMessage(input: { selection: FixSelection; plan: FixValidatedPlan; requester: string }): string {
  return [
    ...todaysCommitLines(input), // unchanged: finding ids and plain-path locations, closing keywords defused
    "",
    requestedBy(input.requester),
  ].join("\n");
}

// renderFixPrBody keeps its prose ("requested by @...") and adds the machine
// line G0's check reads in PR bodies:
//   `Requested-by: @${input.requester}`

import type { ModelFinding } from "./review.js";

export interface GoldenComment { path: string; startLine: number; endLine: number; severity: "high" | "medium" | "low"; defect: string }
export interface GoldCase { id: string; kind: "real" | "clean" | "planted"; team: string; split: "dev" | "holdout"; golden: GoldenComment[] }
export type Judge = (finding: ModelFinding, golden: GoldenComment) => Promise<boolean>;

// Routing table: Haiku 5.5 low for yes/no checks. Calibrated on 50 hand-labelled
// pairs first; below 90% agreement, switch to Sonnet 5.5 medium.
export const JUDGE = { model: "claude-haiku-5-5", effort: "low" } as const;
const LINE_WINDOW = 10;

const near = (f: ModelFinding, g: GoldenComment): boolean =>
  f.path === g.path && f.line >= g.startLine - LINE_WINDOW && f.line <= g.endLine + LINE_WINDOW;

// Only numbers leave this function: no path, code or finding text.
export async function scoreCase(c: GoldCase, findings: ModelFinding[], judge: Judge) {
  const matched = new Set<ModelFinding>();
  const golden: Array<{ severity: GoldenComment["severity"]; caught: boolean }> = [];
  for (const g of c.golden) {
    let caught = false;
    for (const f of findings.filter((x) => !matched.has(x) && near(x, g))) {
      if (await judge(f, g)) { matched.add(f); caught = true; break; }
    }
    golden.push({ severity: g.severity, caught });
  }
  const alarms = findings.filter((f) => f.severity !== "low").length; // unrecognised ranks as high
  return {
    id: c.id, kind: c.kind, team: c.team, split: c.split, golden,
    findings: findings.length,
    matchedFindings: matched.size,
    cleanAlarms: c.kind === "clean" ? alarms : null, // pass bar: mean <= 0.2 per clean PR
  };
}

// One row per Byte finding on a merged PR: ids, severity and enums only,
// never a path or a body (the same rule as runs.jsonl).
export interface FindingFate {
  schema: 1;
  repository: string;
  prNumber: number;
  commentId: number;
  severity: "high" | "medium" | "low" | null;
  fate: "addressed" | "open";
  wrong: boolean;
  mergedAt: string;
}

// Addressed = a later sniff called it fulfilled and sure, or GitHub marks the
// comment outdated at merge (`line` is null: the code under it changed). A
// rebase can also outdate a comment, so the sniff verdict is the stronger signal.
export function findingFate(
  comment: ReviewComment,
  sniff: { verdict: string; sure: boolean } | undefined,
  thumbsDownFromWriters: number,
): Pick<FindingFate, "fate" | "wrong"> {
  const outdated = comment.line === null && typeof comment.original_line === "number";
  const fulfilled = sniff?.verdict === "fulfilled" && sniff.sure;
  return { fate: outdated || fulfilled ? "addressed" : "open", wrong: thumbsDownFromWriters > 0 };
}

import { DEFAULT_MODEL } from "./limits.js";
import type { PullRequestFile } from "./types.js";

export type Effort = "low" | "medium" | "high";
export interface ReviewRoute { model: string; effort: Effort; reason: string }

// Starting values from the routing table. Each route stays only while its
// BYTE-GOLD slice holds (HIGH recall within 3 points of `high`).
const LARGE_PR_LINES = 400;
const GENERATED = /(^|\/)(package-lock\.json|uv\.lock|yarn\.lock)$|_pb2(_grpc)?\.pyi?$/;
const DOCS = /\.(md|mdx|txt)$|(^|\/)docs\//;
const TESTS = /(^|\/)(tests?|e2e|__tests__)\/|\.(test|spec)\.[jt]sx?$|(^|\/)test_[^/]+\.py$/;
const DEPS = /(^|\/)(package\.json|pyproject\.toml|requirements[^/]*\.txt)$/;

export function reviewRoute(files: PullRequestFile[]): ReviewRoute {
  const counted = files.filter((file) => !GENERATED.test(file.filename));
  const lines = counted.reduce((sum, file) => sum + file.additions + file.deletions, 0);
  const all = (pattern: RegExp): boolean => counted.every((file) => pattern.test(file.filename));
  if (all(DOCS) || all(TESTS) || all(DEPS)) {
    return { model: DEFAULT_MODEL, effort: "low", reason: "docs-, test- or dependency-only" };
  }
  if (lines > LARGE_PR_LINES) {
    return { model: DEFAULT_MODEL, effort: "high", reason: `${lines} changed lines` };
  }
  return { model: DEFAULT_MODEL, effort: "medium", reason: `${lines} changed lines` };
}

import { isPathAllowed } from "./policy.js";
import type { PullRequestFile } from "./types.js";

// Per repository in config/repositories.json, baked into the signed image:
// "risk": { "high": { "paths": ["cloud/rhinoCloud/rhinoCore/migrations/**", ...], "reason": "schema change" },
//           "low":  { "paths": ["**/*.md", "**/*.stories.tsx", "**/tests/**"], "reason": "docs or tests only" } }
// Files no rule claims are "med".
export type RiskTier = "low" | "med" | "high";
interface RiskRule { paths: string[]; reason: string }
export interface RiskPolicy { high?: RiskRule; low?: RiskRule }

const RAISE_ABOVE_LINES = 800;
const ORDER: RiskTier[] = ["low", "med", "high"];

export function riskFor(files: PullRequestFile[], policy: RiskPolicy): { tier: RiskTier; reasons: string[] } {
  const { high, low } = policy;
  const reasons: string[] = [];
  let tier: RiskTier = low !== undefined && files.every((f) => isPathAllowed(f.filename, low.paths)) ? "low" : "med";
  const risky = high === undefined ? [] : files.filter((f) => isPathAllowed(f.filename, high.paths));
  if (high !== undefined && risky.length > 0) {
    tier = "high";
    reasons.push(`${risky.length} file(s): ${high.reason}`);
  }
  const lines = files.reduce((sum, f) => sum + f.additions + f.deletions, 0);
  if (lines > RAISE_ABOVE_LINES && tier !== "high") {
    tier = ORDER[ORDER.indexOf(tier) + 1] ?? "high";
    reasons.push(`${lines} changed lines`);
  }
  return { tier, reasons: reasons.length > 0 ? reasons : [tier === "low" ? (low?.reason ?? "low") : "no high-risk paths"] };
}

// Nova's PRs (G4) are drafts opened by the ai-agents App until Byte's review
// is clean. The App is no collaborator, so the person who handed Nova the
// ticket (the Requested-by: line, G0) must have write access instead.
const REQUESTED_BY = /^Requested-by: @([A-Za-z0-9-]{1,39})\s*$/m;

function agentRequester(event: PullRequestEvent, pr: PullRequest, policy: LoadedPolicy): string | undefined {
  const authors = new Set((policy.agentAuthors ?? []).map((login) => login.toLowerCase()));
  const author = pr.user?.login.toLowerCase() ?? "";
  if (!authors.has(author) || event.sender.login.toLowerCase() !== author || pr.base.ref !== "main") {
    return undefined;
  }
  return REQUESTED_BY.exec(pr.body ?? "")?.[1];
}

// In gate(), after the live PR is fetched (the body is read from GitHub, not the event):
if (isAgentEvent) {
  const requestedBy = agentRequester(event, pr, policy);
  if (requestedBy === undefined) {
    return reject("agent PRs need a Requested-by: line naming the person who asked");
  }
  const permission = await readApi.getCollaboratorPermission(repository, requestedBy);
  if (!ALLOWED_PERMISSIONS.has(permission)) {
    return reject("the requester must currently have write, maintain, or admin access");
  }
}

const NEVER_QUIET: ReadonlySet<string> = new Set(["security", "data-loss"]);
const zero = (): Record<FindingSeverity, number> => ({ high: 0, medium: 0, low: 0 });

// Agent PRs (G2-13): post only what Nova should act on. Everything else is a
// number in the check run's severity table, so nothing disappears silently.
export function selectInline(
  findings: ModelFinding[],
  options: { agentPr: boolean; quietCategories: ReadonlySet<string> },
): { inline: ModelFinding[]; counted: Record<"known" | "minor" | "quiet", Record<FindingSeverity, number>> } {
  const counted = { known: zero(), minor: zero(), quiet: zero() };
  if (!options.agentPr) {
    return { inline: findings, counted };
  }
  const inline: ModelFinding[] = [];
  for (const finding of findings) {
    const severity = finding.severity ?? "high"; // unrecognised ranks as high, as in brand.ts
    const category = finding.category ?? "";
    const quiet = options.quietCategories.has(category) && !(severity === "high" && NEVER_QUIET.has(category));
    if (finding.known === true) counted.known[severity] += 1;
    else if (severity === "low") counted.minor[severity] += 1;
    else if (quiet) counted.quiet[severity] += 1;
    else inline.push(finding);
  }
  return { inline, counted };
}

import { REVIEW_INPUT_DIR, SKILLS_ROOT } from "./engines.js";
import { runProcess } from "./process.js";

export type Lens = "correctness" | "security" | "conventions" | "incidents" | "requirements";

// Routing table: Opus 5.5 medium for logic and security; Sonnet 5.5 low for conventions.
const LENS_MODEL: Record<Lens, { model: string; effort: "low" | "medium" }> = {
  correctness: { model: "claude-opus-5-5", effort: "medium" },
  security: { model: "claude-opus-5-5", effort: "medium" },
  conventions: { model: "claude-sonnet-5-5", effort: "low" },
  incidents: { model: "claude-opus-5-5", effort: "medium" },
  requirements: { model: "claude-opus-5-5", effort: "medium" },
};

// Blind lenses read the diff file and the tree only: no gh, so no PR body and no Nova plan.
const BLIND: ReadonlySet<Lens> = new Set(["correctness", "security", "conventions"]);

export async function runLenses(context: PanelContext): Promise<LensFinding[]> {
  const runs = (Object.keys(LENS_MODEL) as Lens[]).map(async (lens) => {
    const tools = [
      "Read(//workspace/**)", "Glob(//workspace/**)", "Grep(//workspace/**)",
      `Read(/${SKILLS_ROOT}/**)`, `Read(/${REVIEW_INPUT_DIR}/**)`,
      ...(BLIND.has(lens) ? [] : ["Bash(gh pr view *)"]),
    ];
    const argv = lensArguments(lens, LENS_MODEL[lens], tools, context); // same safety flags as CLAUDE_BUILTIN
    const result = await runProcess("claude", argv, context.timeoutMs, context.env);
    return parseLensFindings(lens, result.stdout); // bad JSON: retry once, then drop the lens and say so
  });
  return (await Promise.all(runs)).flat();
}

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

type Level = "high" | "medium" | "low";
interface Verdict { verdict: "confirmed" | "refuted" | "unsure"; cite: string; reason: string }
const CITE = /^([A-Za-z0-9._/()-]+):(\d+)$/;
const down = (level: Level): Level => (level === "high" ? "medium" : "low");

// The skeptic must point at real code: a cite that doesn't resolve in the
// checkout turns "confirmed" into "unsure".
export function citeHolds(cite: string, workspace = "/workspace"): boolean {
  const match = CITE.exec(cite.trim());
  const path = match?.[1];
  if (path === undefined || path.split("/").includes("..")) return false;
  const file = join(workspace, path);
  const line = Number(match?.[2]);
  return existsSync(file) && line >= 1 && line <= readFileSync(file, "utf8").split("\n").length;
}

export function applyVerdict(finding: LensFinding, skeptic: Verdict): LensFinding | undefined {
  const verdict = skeptic.verdict === "confirmed" && !citeHolds(skeptic.cite) ? "unsure" : skeptic.verdict;
  if (verdict === "refuted") return undefined;
  if (verdict === "unsure") {
    // The confidence rubric then drops whatever fell to low confidence.
    return { ...finding, severity: down(finding.severity), confidence: down(finding.confidence) };
  }
  return { ...finding, skepticCite: skeptic.cite };
}

import type { RiskTier } from "./risk.js";

export type ReviewMode = "standard" | "deep";
const DEEP_ABOVE_LINES = 800;

// Deep = the panel (lenses, then a skeptic per finding, then rank). Starting
// rule; widened only from the W10 BYTE-GOLD numbers (cost and quality per PR).
export function reviewMode(input: { risk: RiskTier; changedLines: number; asked?: "deep" }): { mode: ReviewMode; reason: string } {
  if (input.asked === "deep") {
    return { mode: "deep", reason: "asked with @byte-review deep" };
  }
  if (input.risk === "high") {
    return { mode: "deep", reason: "risk:high" };
  }
  if (input.changedLines > DEEP_ABOVE_LINES) {
    return { mode: "deep", reason: `${input.changedLines} changed lines` };
  }
  return { mode: "standard", reason: "single review session" };
}
